@model BlogPostListModel

<section class="mx-auto max-w-5xl px-6 py-16">
    @if (!string.IsNullOrEmpty(Model.Heading))
    {
        <h2 class="text-3xl font-bold tracking-tight text-slate-900">@Model.Heading</h2>
    }
    @if (!string.IsNullOrEmpty(Model.Intro))
    {
        <p class="mt-2 text-lg text-slate-600">@Model.Intro</p>
    }

    <div class="mt-10 grid gap-8 sm:grid-cols-2">
        @foreach (var post in Model.Posts)
        {
            <article class="group flex flex-col overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm transition hover:shadow-lg">
                <a href="@post.Url" class="block overflow-hidden bg-slate-100">
                    @if (!string.IsNullOrEmpty(post.ImageUrl))
                    {
                        <img src="@post.ImageUrl" alt="" class="aspect-video w-full object-cover transition duration-300 group-hover:scale-105" loading="lazy" />
                    }
                </a>
                <div class="flex flex-1 flex-col p-6">
                    <p class="text-xs font-semibold uppercase tracking-wide text-indigo-600">
                        <time datetime="@post.Date.ToString("yyyy-MM-dd")">@post.Date.ToString("d MMMM yyyy")</time>
                        @if (!string.IsNullOrEmpty(post.Author))
                        {
                            <span class="text-slate-400"> &middot; </span><span>@post.Author</span>
                        }
                    </p>
                    <h3 class="mt-2 text-xl font-semibold text-slate-900">
                        <a href="@post.Url" class="hover:text-indigo-600">@post.Title</a>
                    </h3>
                    <p class="mt-3 flex-1 text-slate-600">@post.Summary</p>
                    <a href="@post.Url" class="mt-5 text-sm font-semibold text-indigo-600 hover:text-indigo-500">Read more &rarr;</a>
                </div>
            </article>
        }
    </div>

    @if (Model.Posts.Count == 0)
    {
        <p class="mt-10 text-slate-500">No posts yet.</p>
    }
</section>

