@inherits UmbracoViewPage
@{
    var home = Model.AncestorOrSelf<BlogHome>();
    var siteName = home?.SiteName ?? "Blog";
    var seo = Model as ISeoComposition;
    var title = string.IsNullOrWhiteSpace(seo?.MetaTitle) ? Model.Name : seo.MetaTitle;
}
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>@title</title>
    @if (!string.IsNullOrWhiteSpace(seo?.MetaDescription))
    {
        <meta name="description" content="@seo.MetaDescription" />
    }
    <link rel="stylesheet" href="~/dist/site.css" asp-append-version="true" />
</head>
<body class="flex min-h-screen flex-col bg-slate-50 text-slate-800 antialiased">
    <header class="border-b border-slate-200 bg-white">
        <div class="mx-auto flex max-w-5xl items-center justify-between px-6 py-4">
            <a href="@(home?.Url() ?? "/")" class="text-lg font-bold tracking-tight text-slate-900">@siteName</a>
            <span class="text-sm text-slate-500">Built entirely over MCP</span>
        </div>
    </header>

    <main class="flex-1">
        @RenderBody()
    </main>

    <footer class="border-t border-slate-200 bg-white">
        <div class="mx-auto max-w-5xl px-6 py-8 text-sm text-slate-500">
            &copy; @DateTime.Now.Year @siteName. Photos from <a href="https://unsplash.com" class="underline hover:text-slate-700">Unsplash</a>.
        </div>
    </footer>
</body>
</html>

