@import "tailwindcss";

/* Tailwind scans these for class names. Razor views live outside this project,
   so they need an explicit @source; everything under src/ is picked up as well. */
@source "../../Umbraco.Bench.Umbraco/Views";

/* Site-wide styles below. Vue custom elements have their own shadow-DOM styles,
   but content passed into their slots renders in the light DOM and is styled here. */

/* Umbraco's default block grid markup: lay the items out on the grid. */
.umb-block-grid__layout-container {
    display: grid;
    grid-template-columns: repeat(var(--umb-block-grid--grid-columns, 12), minmax(0, 1fr));
}

.umb-block-grid__layout-item {
    grid-column: span var(--umb-block-grid--item-column-span, 12);
    grid-row: span var(--umb-block-grid--item-row-span, 1);
    min-width: 0;
}

/* Rich text block content. */
.rich-text {
    font-size: 1.125rem;
    line-height: 1.8;
    color: var(--color-slate-700);
}

.rich-text > * + * {
    margin-top: 1.25rem;
}

.rich-text h2 {
    margin-top: 2.25rem;
    font-size: 1.75rem;
    font-weight: 700;
    line-height: 1.3;
    color: var(--color-slate-900);
}

.rich-text ul {
    list-style: disc;
    padding-left: 1.5rem;
}

.rich-text li + li {
    margin-top: 0.5rem;
}

.rich-text strong {
    color: var(--color-slate-900);
}

.rich-text a {
    color: var(--color-indigo-600);
    text-decoration: underline;
}

