@using Umbraco.Cms.Core.Models.Blocks
@inherits UmbracoViewPage<BlockGridItem<BlogPostListBlock>>
@{
    var home = UmbracoContext.PublishedRequest?.PublishedContent;
    var posts = (home?.Children<BlogPost>() ?? [])
        .OrderByDescending(post => post.PublishDate)
        .Take(Model.Content.MaxItems > 0 ? Model.Content.MaxItems : int.MaxValue)
        .Select(post => new BlogPostCardModel
        {
            Title = post.Name,
            Url = post.Url(),
            Summary = post.Summary ?? "",
            Author = post.Author ?? "",
            Date = post.PublishDate,
            ImageUrl = post.Thumbnail?.GetCropUrl(width: 800, height: 450),
        })
        .ToList();
    var model = new BlogPostListModel
    {
        Heading = Model.Content.Heading ?? "",
        Intro = Model.Content.Intro ?? "",
        Posts = posts,
    };
}
@await Component.InvokeAsync("BlogPostList", new { model })

